import itertools
import json

def solve_puzzle():
    houses = [1, 2]  # left to right
    names = ['Eric', 'Arnold']
    children = ['Bella', 'Fred']
    foods = ['grilled cheese', 'pizza']

    solutions = []

    for name_perm in itertools.permutations(names):
        for child_perm in itertools.permutations(children):
            for food_perm in itertools.permutations(foods):
                # Constraint 1: The person who is a pizza lover is Arnold.
                # i.e., the house with 'pizza' must have name 'Arnold'
                idx_pizza = food_perm.index('pizza')
                if name_perm[idx_pizza] != 'Arnold':
                    continue

                # Constraint 2: The person who loves eating grilled cheese
                # is directly left of the person whose child is named Fred.
                idx_grilled = food_perm.index('grilled cheese')
                idx_fred = child_perm.index('Fred')
                if not (idx_grilled == idx_fred - 1):
                    continue

                # If all constraints satisfied, record solution
                solution = []
                for i, house in enumerate(houses):
                    solution.append({
                        "House": str(house),
                        "Name": name_perm[i],
                        "Children": child_perm[i],
                        "Food": food_perm[i]
                    })
                solutions.append(solution)

    if not solutions:
        raise ValueError("No solution found")

    # Assuming unique solution; take the first
    sol = solutions[0]
    result = {
        "solution": {
            "header": ["House", "Name", "Children", "Food"],
            "rows": [
                [row["House"], row["Name"], row["Children"], row["Food"]]
                for row in sol
            ]
        }
    }
    return result

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
